import heapq
import sys

def dijkstra(graph, start):
    dist = [float('inf')] * len(graph)
    dist[start] = 0
    visited = [False] * len(graph)
    min_heap = [(0, start)]

    while min_heap:
        current_dist, current_node = heapq.heappop(min_heap)

        if visited[current_node]:
            continue

        visited[current_node] = True

        for neighbor, edge_cost in enumerate(graph[current_node]):
            if not visited[neighbor]:
                new_dist = current_dist + edge_cost
                if new_dist < dist[neighbor]:
                    dist[neighbor] = new_dist
                    heapq.heappush(min_heap, (new_dist, neighbor))

    return dist

def process_config(n, m, dominoes):
    graph = [[] for _ in range(n)]
    for i in range(m):
        k, *dominoes_i = dominoes[i]
        for index in dominoes_i:
            graph[i].append(index)

    return graph

def min_cost_to_destroy(orders):
    graph = process_config(*orders)
    costs = dijkstra(graph, 0)[:-1]  # Exclude the last node as it would be the starting node

    return min(costs)

# Example usage:
