    count, result = {}, {}

    # Count occurrences of each number
    for num in nums:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    # Reduce the occurrence count by 1 to split the difference
    for num in count:
        if count[num] % 2 == 0:
            result[num >> 1] = num % 2
        else:
            result[num >> 1] = 2

    # Adjust for the parity of the count of numbers
