import math

def custom_counting_sort(arr, bit_length):
    count = [0] * 2
    for number in arr:
        mask = 1
        for _ in range(bit_length):
            if number & mask:
                if count[1]:
                    count[0] += 1
                else:
                    count[1] += 1
            mask <<= 1
    return count

def xor_of_prefix(elems):
    # This function returns the xor of prefix in a list of integers.
    prefix_xor = [None] * len(elems)
    prefix_xor[0] = elems[0]
    for i in range(1, len(elems)):
        prefix_xor[i] = prefix_xor[i-1] ^ elems[i]
    return prefix_xor

def custom_sort(nums, mod):
    n = len(nums)
    mask = n - 1
    prefix_xor = [0] * (n + 1)
    prefix_xor[0] = 0

    # Caluculate prefix xor apriori
    for number in nums:
        prefix_xor[min(n - 1, (number + mod) % (2 * mod))] ^= prefix_xor[max(0, (number + mod) % (2 * mod) - 1)]

    # ab initio counting sort: categorize the basic number 'num' binary of nums in base 2*mod(because nums = basis mod seq of x, num)
    # (from numx to numberx mod x)
    numx, x = -1, 2
    for i in range(31, -1, -1):
        count, rem = divmod(x, 2)
        numx |= ((count * numx | rem) << i)
        x *= 2

