# Extended Greatest Common Divisor (EGCD) to compute Euler's Totient function
def egcd(a, b):
    if a == 0:
        return (b, 0, 1)
    gcd, x1, y1 = egcd(b % a, a)
    x = y1 - (b // a) * x1
    y = x1
    return (gcd, x, y)

# Euler's Totient function
def euler_totient(n):
    if n % 2 == 0:
        return (n // 2) if n // 2 > 1 else mod
    mastergcd, x, y = egcd(n, 2)
    return n * pow(n // mastergcd, mastergcd - 1, mod)

