from heapq import heappop, heappush
from bisect import bisect_left

def max_subsegment_sum(segments: List[tuple], starts: List[int]):
    heap = []
    for i in range(len(segments)):
        L, R = segments[i]
        segment = (L, R)
        if not heap:
            heappush(heap, segment)
            starts[i] = -1
        else:
            rightmost = heap[0][1]
            if rightmost > L:
                starts[i] = -1
            if rightmost < L:
                while heap and rightmost >= heap[0][1]:
                    heappop(heap)
                if heap:
                    start, end = heap[0]
                    heappush(heap, (start, rightmost))
                heapsort(heap)
            starts[i] = -heappop(heap)[1]
    return tuple(starts)

def heapsort(heap: List[tuple]):
    for i in range(len(heap)):
        heappop(heap)
    for i in range(len(heap)):
        heappush(heap, tuple(sorted(heap[i+1], reverse=True)))

def main():
