def haiku_count(n, x, y, z):
    mod = 10**9 + 7
    dp = [[0] * (y + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for x in range(1, n + 1):
        for y in range(1, x):
            for z in range(y, x):
                for w in range(z, n):
                    a_sum = sum(range(x, y))
                    b_sum = sum(range(y, z))
                    c_sum = sum(range(z, w))
                    if x == a_sum and y == b_sum and z == c_sum:
                        dp[x][y] += dp[x - 1][z - 1]
                        dp[x][y] %= mod

