def max_baskets(n, k, berries):
    max_baskets = 0
    for a, b in berries:
        if a % k == 0 or b % k == 0:
            max_baskets += min(a, b)
        elif a // k > 0 and b // k > 0:
            max_baskets += (a + b - min(a, b)) // k
    if n > len(berries):
        max_baskets -= berries[:n-len(berries)].count(0)
    return max_baskets

