def min_chars_to_erase(s, x):
    def can_form_x_prime(low, high):
        if low <= high or (sum([int(digit) for digit in s[low:high]]) != x):
            return False
        for mid in range(low + 1, high):
            if sum([int(digit) for digit in s[low:mid]]) % x == 0:
                return False
        return True

    low = 0
    high = len(s) - 1

    while low < high:
        mid = (low + high + 1) // 2
        if can_form_x_prime(low, mid - 1):
            high = mid - 1
        else:
            low = mid

    return low

