def lcm(a, b):
    return a * b // gcd(a, b)

def gcd_extended(a, b):
    if b == 0:
        return a, 1, 0
    else:
        gcd_result, x1, y1 = gcd_extended(b, a % b)
        x = y1
        y = x1 - y1 * (a // b)
        return gcd_result, x, y

