def find_good_subsets(arrays):
    if len(arrays) == 1:
        return 1, arrays

    good_subsets = set()
    for perm in permutations(range(1, len(arrays[0]) + 1)):
        match_array = 0
        for idx, array in enumerate(arrays):
            if array == list(perm):
                match_array = idx
                break
        if match_array == 0:
            continue
        subset = set()
        for idx, array in enumerate(arrays):
            if idx == match_array:
                continue
            if array == list(perm):
                subset.add(idx + 1)
        if not subset or len(subset) == len(arrays[0]):
            good_subsets.add((match_array, tuple(sorted(subset))))

    result = sorted(list(good_subsets), key=lambda x: (x[0], x[1]))
    return len(good_subsets), result

