def max_connected_component(n, k, grid):
    max_connected = 0
    for row in grid:
        if '.' in row:
            max_connected = n**2
    for i in range(k // 2):
        for j in range(k // 2):
            new_grid = [r for r in grid if ''.join(r).find('X') in [(i * k + j + 1) % n for i in range(k) for j in range(k)]]
            if not new_grid:
                continue
            connections = []
            for pos in [(i - 1, j) if i else (1, j), (i + 1, j) if i + 1 == k else (i + 1, j),
                        (i, j - 1) if j else (i, 1), (i, j + 1) if j + 1 == k else (i, j + 1)]:
                if all(0 <= x < n for x, y in [pos] + connections):
                    connections.append(pos)
                    connections.extend([p for p in connections if p in [pos]] * 2)
                    max_connected = max(max([sum(i == '.' for i in ''.join([z for x, y in pos for z in grid[y]]) if i == '.' for i in range(4)]) for pos in connections], default=0)
    return max_connected

