    mod = 10**9 + 7
    dp = [[0] * 41 for _ in range(n + 1)]
    dp[0][0] = dp[0][1] = 1

    for i in range(n):
        for j in range(i + 1):
            for x in range(1, 5):
                dp[i + 1][x] = (dp[i + 1][x] + dp[j][x - 1]) % mod

    for j in range(1, n):
        for x in range(5):
            for y in range(4):
                if x + y > z - 1:
                    break
                dp[j + 1][0] += dp[j][x] * dp[j][y]
                dp[j + 1][y] += dp[j][x] * dp[j][y]
            dp[j + 1][x] = (dp[j + 1][x] - dp[j][x] * dp[j][x]) % mod
            if x + y > z - 1:
                break

        for y in range(1, n - j):
            for x in range(4):
                if x + y + 1 > z:
