                dp[j + 1][0] += dp[j][x] * dp[j + y][0]
                dp[j + 1][y] += dp[j][x] * dp[j + y][0]
            dp[j + 1][x] = (dp[j + 1][x] - dp[j][x] * dp[j + y][0]) % mod
            if x + y + 1 > z:
