import math

def find_area(n, l, pins):
    x, y = zip(*pins)
    x.sort()
    y.sort()
    def perimeter(a, b, c):
        return x[b] - x[a] + y[c] - y[a] + x[c] - x[b] + y[b] - y[c]
    def det(a, b, c):
        return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])

    total = 0
    for i in range(n):
        a, b, c = pins[i-1], pins[i], pins[(i-1 + n) % n]
        if det(a, b, c) < 0:
            continue
        dp, di = [0], 1
        for j in range(i + 1, n):
            d = i - (j % n)
            if i < n - 1:
                dp, di = [max(dp[0] + l, dp[-1] + l)] + [max(dp[k] + perimeter(dp[k], i, j), dp[k] + perimeter(dp[k], j, i)) for k in range(len(dp))], (di + 1) % di
            for k in range(len(dp)):
                total += (dp[k] + dp[k+1]) * area(dp[k-1], dp[k], dp[k+1]) / (di+2)
    return total

def area(p1, p2, p3):
    return p1[0] * (p2[1] - p3[1]) + p2[0] * (p3[1] - p1[1]) + p3[0] * (p1[1] - p2[1])

