from math import gcd
from functools import lru_cache

def modular_inverse(a, mod):
    return fast_modular_pow(a, mod - 2, mod)

def fast_modular_pow(x, y, mod):
    res = 1
    power = x
    while y:
        if y & 1: res = (res * power) % mod
        y >>= 1
        power = (power * power) % mod
    return res

def modular_reduce(x, mod):
    return fast_modular_pow(x, mod - 2, mod)

@lru_cache(maxsize=32768)
def recursive_solution(n, index, last_result, last_element):
    min_n, max_n = 1, 1
    if index == 1:
        min_n = last_element
        max_n = last_result

    l_divisors = [i, n - i]
    r_divisors = [j, n - j]

    for l_current, r_current in zip(l_divisors, r_divisors):
        result = recursive_solution(l_current - 1, index - 1, last_result & l_current, l_current) ^ recursive_solution(r_current - 1, index - 1,
                                                                                                                                          last_result & r_current,
                                                                                                                                          r_current)
        result ^= last_result & index

        if last_result % (l_current * r_current) == 0:
            result ^= modular_reduce(last_result, l_current * r_current)
        if last_element % (l_current * r_current) == 0:
            result ^= modular_reduce(last_element, l_current * r_current)
        res_seq = ((n / (l_current * r_current) - 1) * r_divisors +
                   (1 - (n / (l_current * r_current))) * l_divisors)
        if max_n > 0:
            res_seq = sorted(res_seq, reverse=True)
        if min_n > 0:
            res_seq = sorted(res_seq)
        min_n = res_seq[0]
        max_n = res_seq[-1]

    return index * 2, min_n, max_n

def solve_solution(n, seq):
    index, last_result, last_element = 0, '0', '0'
    x1, x2 = recursive_solution(n, n, '0', '0')
    y1, y2 = recursive_solution(x1, x1, last_result ^ '0', last_element)
    z1, z2 = recursive_solution(y1, y1, '0', '0')
    y3, y4 = recursive_solution(z1, z2, last_result ^ '0', last_element)
    y5, y6 = recursive_solution(y3, y4, last_result ^ last_element, last_element)

    return seq[:int(m)]
