def count_digits(number):
    return len(str(number))

def f(l, r, s):
    return sum(int(c) for c in s[l:r+1])

def is_prime(x):
    if x == 1:
        return False
    elif x == 2:
        return True
    elif x % 2 == 0:
        return False
    for imax in range(3, int(x ** 0.5) + 1, 2):
        if x % imax == 0:
            return False
    return True

def compute_min_erasure(s, x):
    n = len(s)
    dp = [[float('inf')] * n for _ in range(10)]
    for i in range(n):
        dp[i][count_digits(int(s[i]))] = max(1, f(i, i, s) - x)
    for j in range(1, n):
        for i in range(j):
            strict_sum = f(i, j-1, s)
            if i > 0 and is_prime(strict_sum-x) and not dp[i-1][strict_sum-x] + 1 <= dp[i][count_digits(int(s[j]))]:
                dp[i][count_digits(int(s[j]))] = dp[i-1][strict_sum-x] + 1
            elif not is_prime(strict_sum-x) and not dp[i][count_digits(int(s[j]))] > 1:
                dp[i][count_digits(int(s[j]))] = 1
    return min(dp[n-1])

